from comun import S, pca, navas24, navas16

G = []


def g(termino, definicion, fuente, sub):
    G.append({"id": "g-" + termino.lower().replace(" ", "-").replace("(", "").replace(")", "").replace("/", "-").replace(",", "")
              .replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u").replace("ñ", "n"),
              "termino": termino, "definicion": definicion, "tema": 3, "subtema": sub, "fuente": fuente})


g("Agregado", "Material granular, como arena, grava o roca triturada, que se usa con un medio cementante para hacer concreto o mortero.", [S("19", 6)], "3A")
g("Agregado fino", "Agregado que pasa la malla No. 4 (4,75 mm) y queda retenido en la No. 200 (75 µm); se le conoce como arena.", [navas16(18), S("19", 6)], "3D")
g("Agregado grueso", "Agregado que queda retenido en la malla No. 4 (4,75 mm); se le conoce como piedra.", [navas16(18), S("19", 6)], "3D")
g("Agregado liviano", "Agregado con peso unitario masivo seco menor que 1120 kg/m³, como la pómez, la escoria o las cenizas volcánicas.", [S("14", 9), S("19", 67)], "3A")
g("Agregado pesado", "Agregado con peso unitario masivo seco mayor que 1900 kg/m³, como la barita o la magnetita; se usa en concreto de blindaje contra la radiación.", [S("14", 9), S("14", 10)], "3A")
g("Absorción (D)", "Porcentaje de agua que llena los poros permeables respecto del peso seco: D = PWD/Ps × 100.", [S("19", 66)], "3C")
g("Agua libre", "Agua en la superficie de las partículas, por encima de la absorción (w > D). Es la que causa el hinchamiento de la arena.", [S("13", 2), navas24(6)], "3C")
g("Saturado superficie seca (SSS)", "Condición en la que los poros permeables están llenos de agua pero no hay agua libre en la superficie (w = D). El agregado no absorbe ni cede agua.", [S("19", 65), navas24(6)], "3C")
g("Hinchamiento (abundamiento)", "Aumento del volumen masivo de la arena húmeda respecto de su volumen seco, causado por el agua libre y la tensión superficial: H = ΔV/Vm.", [navas24(6), S("13", 10)], "3C")
g("Volumen bruto (VB)", "Volumen de las partículas incluidos sus poros permeables e impermeables: VB = Vs + Vpp. No incluye los vacíos entre partículas.", [S("13", 4), navas24(8)], "3C")
g("Volumen masivo (Vm)", "Volumen que ocupa una masa de agregado, incluidos los vacíos entre partículas.", [navas24(12)], "3C")
g("Densidad aparente (δs)", "Masa por unidad de volumen de la porción impermeable (sólida) de las partículas: δs = Ps/Vs.", [S("19", 63)], "3C")
g("Densidad bruta seca (δBS)", "Masa del agregado seco al horno entre el volumen de las partículas, con poros permeables e impermeables y sin los vacíos entre partículas.", [S("19", 64), S("13", 6)], "3C")
g("Gravedad específica (densidad relativa)", "Razón adimensional entre la densidad del agregado y la del agua a una temperatura declarada. Se usa para calcular el volumen que ocupa el agregado en el diseño por volumen absoluto.", [S("19", 62), pca(114)], "3C")
g("Peso unitario (densidad masiva, δb)", "Masa de una unidad de volumen de agregado, contando las partículas y los vacíos entre ellas. Se determina suelto o varillado con la ASTM C29.", [S("19", 99)], "3C")
g("Vacíos", "Espacio entre las partículas de una masa de agregado que no ocupa el material. Son de 30 % a 45 % en el grueso y de 40 % a 50 % en el fino.", [S("19", 99), pca(114)], "3C")
g("Porosidad (n)", "Razón entre el volumen de vacíos y el volumen masivo: n = Vv/Vm.", [S("13", 10)], "3C")
g("Razón de vacíos (e)", "Razón entre el volumen de vacíos y el volumen sólido: e = Vv/Vs.", [S("13", 10)], "3C")
g("Masa constante", "Condición en la que secados posteriores causan una pérdida de masa menor que 0,1 %.", [S("19", 37)], "3E")
g("Granulometría", "Distribución porcentual en masa de los tamaños de partícula de un agregado, determinada por tamizado.", [S("19", 47)], "3D")
g("Porcentaje retenido acumulado", "Suma del porcentaje retenido en una malla y en todas las mallas de mayor abertura.", [S("19", 47)], "3D")
g("Porcentaje pasando", "100 % menos el porcentaje retenido acumulado en esa malla.", [S("19", 47)], "3D")
g("Tamaño máximo", "La malla más pequeña por la que pasa el 100 % del material.", [S("19", 9)], "3D")
g("Tamaño máximo nominal", "El mayor tamaño de malla donde queda retenido material, respetando un retenido máximo permisible.", [S("19", 9)], "3D")
g("Módulo de finura (MF)", "Suma de los porcentajes retenidos acumulados en las mallas No. 4, 8, 16, 30, 50 y 100, dividida entre 100. Es un índice de finura: a mayor MF, más grueso.", [S("19", 48)], "3D")
g("Suficiencia de tamizado", "Tamizado manual adicional, malla por malla, hasta que pase menos del 1 % de lo retenido.", [S("19", 53)], "3E")
g("Cuarteo", "Método B de la ASTM C702: se apila en cono, se aplana, se divide en cuatro y se retiran dos cuartos opuestos.", [S("19", 29)], "3E")
g("Separador mecánico", "Equipo de canales de igual ancho que divide la muestra en dos mitades (método A de la ASTM C702).", [S("19", 25)], "3E")
g("Picnómetro", "Matraz de volumen reproducible que se usa en la ASTM C128 para determinar el volumen de la arena por el método gravimétrico.", [S("19", 81)], "3E")
g("Máquina de Los Ángeles", "Cilindro de acero rotatorio con esferas de acero que mide la degradación del agregado grueso por abrasión e impacto (ASTM C131).", [S("19", 114)], "3E")
g("Reacción álcali-sílice (RAS)", "Reacción entre el hidróxido alcalino del concreto y la sílice reactiva del agregado; forma un gel expansivo que genera presiones internas.", [S("15", 16), pca(122)], "3B")
g("Reacción álcali-carbonato (RAC)", "Reacción de ciertas rocas dolomíticas con los álcalis; el producto agrieta la pasta. Se evalúa con la ASTM C586.", [S("15", 18), pca(126)], "3B")
g("Álcalis del cemento", "Óxidos de sodio (Na₂O) y de potasio (K₂O) del cemento.", [S("15", 15)], "3B")
g("Dolomita", "Carbonato de calcio y magnesio; las rocas dolomíticas pueden producir reacción álcali-carbonato.", [pca(126), S("15", 18)], "3B")
g("Meteorización", "Debilitamiento de los minerales por la humedad, los cambios de temperatura y los agentes químicos (hidrólisis, oxidación, hidratación y disolución).", [S("26", 17), S("26", 34)], "3B")
g("Roca ígnea", "Roca que se forma por el enfriamiento de un magma; su textura depende de la velocidad de enfriamiento.", [S("26", 9)], "3B")
g("Roca sedimentaria", "Roca que se forma en la superficie por meteorización, erosión y cementación (clásticas) o por precipitación química (químicas).", [S("26", 9), S("26", 59)], "3B")
g("Roca metamórfica", "Roca que resulta de someter otras rocas a muy altas presiones y temperaturas, de modo que recristalizan; por ejemplo, el mármol.", [S("26", 9)], "3B")
g("Ignimbrita", "Roca piroclástica muy soldada, depositada a muy alta temperatura; por su soldamiento puede servir para construcción.", [S("26", 45)], "3B")
g("Petrografía", "Estudio que describe los minerales de una roca: tipo, tamaño, forma, entrelazamiento, poros, fracturas y vetillas.", [S("26", 7)], "3B")
g("Partícula plana", "Partícula cuya relación espesor/ancho es menor que 0,5 (ASTM D4791).", [S("15", 19)], "3A")
g("Partícula elongada", "Partícula cuya relación largo/ancho es mayor que 1,5 (ASTM D4791).", [S("15", 19)], "3A")
g("Escoria de alto horno", "Agregado artificial, subproducto de la producción de acero; sus componentes principales son sílice, alúmina y cal.", [S("14", 8)], "3A")
